// FILE: Streamly.Benchmarks/IrsBurstOpenBenchmark.cs
//
// Same measurement as BurstOpenBenchmark but using IrsRequest payloads.
//
// Goals vs the SpotPrice benchmark:
//   - IrsPrice response is ~3x larger (600-900 bytes vs ~200 bytes)
//   - IrsRequest SHA256 hashing is heavier (more fields to serialize)
//   - Exercises the full mixed decimal/double/DateTime serialization path
//   - Confirms the burst-open fix holds under heavier per-message CPU cost
//
// Requests are generated by IrsRequestFactory so each of the N streams maps
// to a distinct RequestId on the publisher — no deduplication short-circuit.
//
// Launch order:
//   1. nats-server -js
//   2. Streamly.Test.Publisher  (must have IrsPricer handler registered)
//   3. dotnet run -c Release

using System.Collections.Concurrent;
using System.Diagnostics;
using BenchmarkDotNet.Attributes;
using Streamly.Core.Models;

namespace Streamly.Benchmarks;

[Config(typeof(StreamlyBenchmarkConfig))]
[MemoryDiagnoser]
public class IrsBurstOpenBenchmark
{
    private BenchmarkHarness _harness = null!;

    [Params(1000, 5000, 10000)]
    public int N;

    // Pre-generated requests — stable across iterations so the publisher
    // sees the same RequestIds every run (warm SHA256 / registry paths).
    private IReadOnlyList<IrsRequest> _requests = null!;

    private ConcurrentBag<IDisposable> _subscriptions = new();

    [GlobalSetup]
    public async Task GlobalSetup()
    {
        // Generate the maximum N upfront so all param values reuse the same
        // list — requests[0..N] is used per iteration.
        _requests = IrsRequestFactory.Generate(10_000);
        _harness = new BenchmarkHarness();
        await _harness.StartAsync();
    }

    [GlobalCleanup]
    public async Task GlobalCleanup()
    {
        DrainAndDispose(ref _subscriptions);
        await _harness.DisposeAsync();
    }

    [IterationCleanup]
    public void IterationCleanup()
    {
        DrainAndDispose(ref _subscriptions);
        // Give the publisher time to drain its registry before the next
        // iteration floods it with the same N RequestIds again.
        Thread.Sleep(5000);
    }

    [Benchmark]
    public async Task<double> TimeToLastFirstPrice()
    {
        var remaining = N;
        var tcs = new TaskCompletionSource<double>(
            TaskCreationOptions.RunContinuationsAsynchronously);

        var sw = Stopwatch.StartNew();

        var tasks = new Task[N];
        for (var i = 0; i < N; i++)
        {
            var request = _requests[i]; // capture — distinct IrsRequest per stream
            tasks[i] = Task.Run(() =>
            {
                var sub = _harness.IrsSubscriber
                    .Subscribe(
                        request,
                        behavior: StreamBehavior.Live)
                    .Subscribe(
                        onNext: _ =>
                        {
                            // Last subscriber to receive its first price stops the clock.
                            if (Interlocked.Decrement(ref remaining) == 0)
                                tcs.TrySetResult(sw.Elapsed.TotalMilliseconds);
                        },
                        onError: _ =>
                        {
                            // Count errors down so the benchmark never deadlocks.
                            // Anomalous runs show up as outliers in the CSV.
                            if (Interlocked.Decrement(ref remaining) == 0)
                                tcs.TrySetResult(sw.Elapsed.TotalMilliseconds);
                        });

                _subscriptions.Add(sub);
            });
        }

        await Task.WhenAll(tasks);

        using var cts = new CancellationTokenSource(TimeSpan.FromMinutes(5));
        cts.Token.Register(() =>
            tcs.TrySetException(new TimeoutException(
                $"Only {N - remaining}/{N} IRS streams received first price within 5 min.")));

        return await tcs.Task;
    }

    private static void DrainAndDispose(ref ConcurrentBag<IDisposable> bag)
    {
        var snapshot = Interlocked.Exchange(ref bag, new ConcurrentBag<IDisposable>());
        while (snapshot.TryTake(out var sub))
            sub.Dispose();
    }
}
